def removeOccurrences(s: str, part: str) -> str:
    stack = []
    plen = len(part)
    for c in s:
        stack.append(c)  # Add char to result
        # Check if we have a potential match at the end
        if len(stack) >= plen and ''.join(stack[-plen:]) == part:
            # Remove the matched part from the end
            for _ in range(plen):
                stack.pop()
    return ''.join(stack)
